# --- SSL: trusted HTTPS via qip ---
# -- uhttpd HTTPS (admin interface) --
if [ -f /etc/tollgate/ssl/server.crt ] && [ -f /etc/tollgate/ssl/server.key ]; then (uci -q revert uhttpd 2>/dev/null || true) && uci set uhttpd.main.cert='/etc/tollgate/ssl/server.crt' && uci set uhttpd.main.key='/etc/tollgate/ssl/server.key' && (uci -q delete uhttpd.main.listen_https || true) && uci add_list uhttpd.main.listen_https='0.0.0.0:443' && uci add_list uhttpd.main.listen_https='[::]:443' && uci commit uhttpd && uci -q get uhttpd.main.listen_https | grep -q '0.0.0.0:443' && /etc/init.d/uhttpd restart && echo 'ssl: uhttpd HTTPS wired on :443'; else echo 'ssl: /etc/tollgate/ssl certs not present yet — skipping uhttpd HTTPS wiring (deploy certs, then re-run)' >&2; fi
